import React, { useState } from 'react'
import getKey from '../utils/KeyGenerator';
import icons from '../site/icons';

const Ingredient = ({
    ingredient
}) => {
    const [check, setCheck] = useState(false);
    const toggleIngredient = () => setCheck(prev => !prev);
    const getCheckBox = (item) => <input
        id={`${item}`}
        name={`${item}`}
        className='regular-checkbox button glassy m-5'
        checked={check}
        type='checkbox'
        onChange={toggleIngredient}
    />
    const removeIngredient = (ingredient) => (e) => {
        //e.stopPropagation();
        // Implement removal logic here
        console.log(`Remove ingredient: ${ingredient}`);
    }
    //console.log(`Ingredient => ingredient: ${JSON.stringify(ingredient, null, 2)}`);
    return (
        <div key={getKey(ingredient)} className='containerBox flexContainer button'>
            <div className='containerBox flexColumn columnRightAlign bold color-yellow'>
                {getCheckBox(ingredient)}
            </div>
            <div className='containerBox flex2Column columnLeftAlign p-15'>
                {ingredient}
            </div>
            <div className='containerDetail p-15 button flexColumn columnRightAlign' title='remove' onClick={() => removeIngredient(ingredient)}>
               {icons.delete}
            </div>
        </div>
    )
}

export default Ingredient